import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Shield, User, LogOut, Globe, ShieldAlert, FileSearch, Lock, Server, Menu, X } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  const scrollToSection = (sectionId) => {
    setMobileMenuOpen(false);
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 150);
    } else {
      const element = document.getElementById(sectionId);
      if (element) element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav className="soc-navbar" style={{ padding: '8px 24px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
        
        {/* Logo / Title */}
        <div 
          onClick={() => scrollToSection('hero-section')} 
          style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}
        >
          <Shield size={22} color="var(--accent-cyan)" />
          <span className="hacker-glow" style={{ fontSize: '14px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
            NET_SENTINEL // SOC
          </span>
        </div>

        {/* Hamburger Three-Line Menu Toggle (Android / iOS view only) */}
        <button 
          className="mobile-menu-btn" 
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle Navigation Menu"
        >
          {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
        </button>

        {/* Navigation Links (Compact Desktop Bar & Mobile Drawer) */}
        <div className={`nav-links-container ${mobileMenuOpen ? 'mobile-open' : ''}`} style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          
          <button onClick={() => scrollToSection('tool-host')} className="cyber-nav-btn" style={{ padding: '5px 8px', fontSize: '11px' }}>
            <Globe size={12} color="var(--accent-cyan)" /> HOST INTEL
          </button>

          <button onClick={() => scrollToSection('tool-port')} className="cyber-nav-btn" style={{ padding: '5px 8px', fontSize: '11px' }}>
            <ShieldAlert size={12} color="var(--alert-red)" /> PORT CVE
          </button>

          <button onClick={() => scrollToSection('tool-subdomain')} className="cyber-nav-btn" style={{ padding: '5px 8px', fontSize: '11px' }}>
            <FileSearch size={12} color="var(--warning-amber)" /> SUBDOMAINS
          </button>

          <button onClick={() => scrollToSection('tool-dir')} className="cyber-nav-btn" style={{ padding: '5px 8px', fontSize: '11px' }}>
            <Lock size={12} color="var(--accent-green)" /> DIR EXPOSURE
          </button>

          <button onClick={() => scrollToSection('tool-ssl')} className="cyber-nav-btn" style={{ padding: '5px 8px', fontSize: '11px' }}>
            <Server size={12} color="var(--accent-cyan)" /> SSL AUDIT
          </button>

          {user ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginLeft: '4px' }}>
              <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '11px' }}>
                [{user.name}]
              </span>
              <button className="cyber-nav-btn" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '5px 6px' }}>
                <LogOut size={12} />
              </button>
            </div>
          ) : (
            <Link to="/login" className="cyber-nav-btn" onClick={() => setMobileMenuOpen(false)} style={{ padding: '5px 10px', fontSize: '11px', backgroundColor: 'rgba(0, 243, 255, 0.15)' }}>
              <User size={12} /> LOGIN
            </Link>
          )}
        </div>

      </div>
    </nav>
  );
}
